	if logPath := strings.TrimSpace(os.Getenv("LOG_PATH")); logPath != "" {
		return filepath.Join(filepath.Dir(logPath), "llm_debug")
	}
	if macPath := defaultMacAppLogPath(); macPath != "" {
		return filepath.Join(filepath.Dir(macPath), "llm_debug")
	}
