    "B1": "电阻制动、再生制动、涡流制动有什么区别？",
    "B2": "这几种制动方式里，哪些能回收能量，哪些只是把能量变成热？",
    "C1": "变频器驱动的电机为什么会出现轴承损坏，怎么防止？",
    "C2": "伺服驱动里为什么要设死区？",
    "D1": "本质安全是什么，它属于哪一类防爆思路？",
    "D2": "预防性维护属于设备生命周期的哪个阶段？",
    "E1": "AC4000 型电力机车是哪一年研制成功的，由哪家单位研制？",
    "F1": "西门子 S120 变频器的 p1120 参数是什么含义？",
    "F2": "我们车间 3 号机床上次保养是哪天？",
    "F3": "PROFIBUS 和 PROFINET 有什么区别？",
    "H3": "刚才说的绝缘轴承装在哪一端？",
}


def call(path, data=None, tok=None, method=None, raw=False, timeout=280):
    h = {"Content-Type": "application/json"}
    if tok:
        h["Authorization"] = "Bearer " + tok
    body = json.dumps(data, ensure_ascii=False).encode("utf-8") if data is not None else None
    r = urllib.request.Request(B + path, data=body, headers=h,
                               method=method or ("POST" if body else "GET"))
    resp = urllib.request.urlopen(r, timeout=timeout)
    return resp if raw else json.loads(resp.read().decode("utf-8"))


def token():
    d = call("/api/v1/auth/auto-setup", {})

    def find(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if k in ("token", "access_token") and isinstance(v, str) and len(v) > 20:
                    return v
                r = find(v)
                if r:
                    return r
        if isinstance(o, list):
            for v in o:
                r = find(v)
                if r:
                    return r
    return find(d)


AGENT_CFG = {
    "agent_id": "builtin-quick-answer", "agent_enabled": False, "model_id": MODEL,
    "knowledge_base_ids": [KB],
    "mentioned_items": [{"id": KB, "name": "工业维护知识库", "type": "kb",
                         "kb_type": "document", "kb_id": "", "kb_name": "",
                         "service_id": "", "skill_name": ""}],
    "web_search_enabled": False,
}


def new_session(tok, title):
    s = call("/api/v1/sessions", {"title": "用例-" + title, "agent_config": AGENT_CFG}, tok)
    return (s.get("data") or s)["id"]


def ask(tok, sid, query):
    body = {"query": query, "agent_enabled": False, "knowledge_base_ids": [KB],
            "agent_id": "builtin-quick-answer", "web_search_enabled": False,
            "summary_model_id": MODEL, "channel": "web"}
    t = time.time()
    first, ans, refs = None, [], []
    for line in call("/api/v1/knowledge-chat/%s" % sid, body, tok, raw=True):
        s = line.decode("utf-8", "replace").strip()
        if not s.startswith("data:"):
            continue
        p = s[5:].strip()
        if not p or p == "[DONE]":
            continue
        try:
            ev = json.loads(p)
        except Exception:
            continue
        rt = ev.get("response_type")
        if rt == "references":
            refs = ev.get("knowledge_references") or ev.get("references") or []
        elif rt == "answer":
            if first is None:
                first = time.time() - t
            ans.append(ev.get("content") or "")
    txt = "".join(ans)
    return {"query": query, "session_id": sid, "answer": txt,
            "elapsed": round(time.time() - t, 1), "first_token": round(first or -1, 1),
            "ref_docs": sorted({(r.get("knowledge_title") or r.get("knowledge_id", "?")) for r in refs}),
            "ref_count": len(refs),
            "cjk": round(len(re.findall(r"[一-鿿]", txt)) / max(len(txt), 1), 2),
            "image_md": bool(re.search(r"!\[[^\]]*\]\(", txt)),
            "ext_link": bool(re.search(r"https?://", txt)),
            "kb_cites": txt.count("<kb "),
            "cite_docs": sorted(set(re.findall(r'<kb doc="([^"]+)"', txt)))}


def main():
    results = {}
    if os.path.exists(OUT):
        results = json.load(open(OUT, encoding="utf-8"))
    tok = token()
    sessions = {}
    for spec in sys.argv[1:]:
        parts = spec.split(">")
        sid = None
        for cid in parts:
            if sid is None:
                sid = sessions.get(parts[0]) or new_session(tok, parts[0])
                sessions[parts[0]] = sid
            r = ask(tok, sid, QUERIES[cid])
            results[cid] = r
            print("%s | %.1fs | refs=%d | cjk=%.2f | img=%s | link=%s | cites=%d %s"
                  % (cid, r["elapsed"], r["ref_count"], r["cjk"], r["image_md"],
                     r["ext_link"], r["kb_cites"], r["cite_docs"]))
            json.dump(results, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)


main()

